fn test_blocked_finish_then_alternating_flush_and_finish() {
    let input = noisy_input(200 * 1024);
    let expected = reference_encode(&input);

    let mut z = Encoder::new(BlockableWriter::new(7), 1).unwrap();
    z.write_all(&input).unwrap();

